 "<i lang=\"it\" translate=\"no\">credere → creduto</i>": "<i lang=\"it\" translate=\"no\">credere → creduto</i>",
 "<b><span lang=\"it\" translate=\"no\">-ire</span></b> → <b style=\"color:#c4572e\"><span lang=\"it\" translate=\"no\">-ito</span></b>": "<b><span lang=\"it\" translate=\"no\">-ire</span></b> → <b style=\"color:#c4572e\"><span lang=\"it\" translate=\"no\">-ito</span></b>",
 "<i lang=\"it\" translate=\"no\">dormire → dormito</i>": "<i lang=\"it\" translate=\"no\">dormire → dormito</i>",
 "Irregolari": "Irregolari",
 "Participio": "Participio",
 "Esempio": "Esempio",
