 "<div style=\"font-family:'Montserrat', sans-serif;font-size:44px;font-weight:800;color:#1f4e9c\"><span lang=\"pt\" translate=\"no\">Boa tarde</span></div><div style=\"font-size:24px;color:#5a6680;margin-top:6px\">Buenas tardes</div>": "<div style=\"font-family:'Montserrat', sans-serif;font-size:44px;font-weight:800;color:#1f4e9c\"><span lang=\"pt\" translate=\"no\">Boa tarde</span></div><div style=\"font-size:24px;color:#5a6680;margin-top:6px\">Goedemiddag</div>",
